te;inset:0;pointer-events:none;box-shadow:inset 0 0 90px 20px #08090bd1,inset 0 0 0 1px #e6c7950c}.hud-top{position:absolute;top:20px;left:22px;right:22px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.hero-card,.wave-card,.kill-card{background:linear-gradient(135deg,#17191be8,#17191bc7);border:1px solid #c1a47738;box-shadow:0 8px 25px #0004;backdrop-filter:blur(8px)}.hero-card{width:213px;height:68px;padding:10px;display:flex;gap:10px;align-items:center}.hero-portrait{height:44px;width:42px;display:grid;place-items:center;background:linear-gradient(145deg,#5b4b37,#28241f);border:1px solid #c7a46d6b;color:#e4c890;font-size:24px}.hero-info{flex:1;position:relative}.hero-label{font-size:8px;letter-spacing:1.2px;color:#d5c6ad}.health-row{display:flex;gap:3px;margin:6px 0 4px}.heart{height:6px;flex:1;background:#592f2b;border:1px solid #8e4d40}.heart.full{background:#bd6652;border-color:#e28b68;box-shadow:0 0 7px #c95d4b77}.health-caption{position:absolute;right:0;bottom:-1px;color:#9d968a;font:8px 'DM Mono',monospace}.wave-card{width:220px;padding:10px 15px 11px;text-align:center}.wave-label{font-size:8px}.wave-label b{color:var(--gold);font-weight:500}.wave-card strong{display:block;color:#e7dac6;font:12px 'Playfair Display',serif;letter-spacing:1.5px;margin:5px 0 8px}.wave-progress{height:2px;background:#49443d}.wave-progress span{display:block;width:0;height:100%;background:#d7ac70;box-shadow:0 0 6px #d7ac70;transition:width .25s}.kill-card{display:flex;align-items:center;gap:9px;padding:10px 14px;height:49px;color:#d4c7b2;font:9px 'DM Mono',monospace;letter-spacing:.8px}.kill-card b{font:18px 'Playfair Display',serif;color:#e1c18c;margin-right:3px}.kill-skull{font-size:19px;color:#bd8064}.objective{position:absolute;top:106px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;color:#c5baa8;font:9px 'DM Mono',monospace;letter-spacing:1.3px;text-shadow:0 2px 6px #000;white-space:nowrap;pointer-events:none}.objective-icon{color:#d5aa6e;font-size:14px}.bottom-hud{position:absolute;left:22px;right:22px;bottom:18px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.weapon-card{height:65px;width:236px;display:flex;align-items:center;gap:11px;padding:8px 10px;background:linear-gradient(135deg,#17191bee,#17191bd4);border:1px solid #c1a47745;box-shadow:0 8px 25px #0005}.weapon-icon{width:40px;height:46px;background:#302a22;border:1px solid #c1a47752;display:grid;place-items:center;color:#e3c893;font-size:23px;text-shadow:0 0 12px #ddb976}.weapon-card>div:nth-child(2){display:flex;flex-direction:column;gap:3px;flex:1}.weapon-label{font-size:7px;letter-spacing:1px}.weapon-card strong{font:11px 'Playfair Display',serif;letter-spacing:.7px;color:#e9dec9}.weapon-sub{font:8px 'DM Mono',monospace;color:#a19a8c}.weapon-damage{font:18px 'Playfair Display',serif;color:#d8b27e;display:flex;flex-direction:column;text-align:center;line-height:1}.weapon-damage span{font:7px 'DM Mono',monospace;color:#9c9385;margin-top:3px}.controls-hint{margin-bottom:8px;color:#aaa49a;font:9px 'DM Mono',monospace;letter-spacing:1px;text-shadow:0 1px 5px #000}.controls-hint i{font-style:normal;color:#726758;margin:0 7px}.keycap{padding:4px 6px;border:1px solid #8e7a5a73;background:#171817b8;color:#d0b782;font-size:8px}.mini-map-wrap{width:124px;padding:6px 6px 5px;text-align:center;background:#17191bd9;border:1px solid #c1a47738}.mini-map-wrap>span{display:block;font-size:7px;letter-spacing:1.2px;margin-bottom:3px}.mini-map-wrap canvas{display:block;width:112px;height:72px;opacity:.9}.toast{position:absolute;top:48%;left:50%;transform:translate(-50%,-50%);padding:11px 20px;background:#17191be8;border:1px solid #b9986470;color:#e4d6c1;font:9px 'DM Mono',monospace;letter-spacing:1.4px;box-shadow:0 8px 25px #0007;opacity:0;transition:opacity .35s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1}.toast-icon{color:var(--gold);margin-right:9px}.upgrade-overlay,.gameover-overlay{position:absolute;inset:0;display:grid;place-items:center;background:#08090bc9;backdrop-filter:blur(5px);opacity:0;pointer-events:none;transition:opacity .25s;z-index:5}.upgrade-overlay.visible,.gameover-overlay.visible{opacity:1;pointer-events:auto}.upgrade-panel{width:min(550px,calc(100% - 32px));padding:32px;background:linear-gradient(145deg,#242220,#171819);border:1px solid #b998646b;box-shadow:0 20px 70px #000a;text-align:center}.eyebrow{color:#c39b65}.upgrade-panel h2{font:30px 'Playfair Display',serif;margin:10px 0 5px;color:#eee0cb}.upgrade-panel p{color:#a7a093;font-size:12px;margin:0 0 23px}.upgrade-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.upgrade-option{border:1px solid #9a835149;background:#1a1b1c;padding:14px 10px;cursor:pointer;transition:.18s;min-height:140px;color:#e4d6c1}.upgrade-option:hover,.upgrade-option.selected{transform:translateY(-3px);border-color:#d5ae70;background:#29251f;box-shadow:0 5px 20px #d5ae7022}.upgrade-option .option-icon{font-size:24px;color:#d3ad73;display:block;margin-bottom:9px}.upgrade-option strong{font:12px 'Playfair Display',serif;display:block;letter-spacing:.5px}.upgrade-option small{font:9px 'DM Mono',monospace;color:#aaa194;line-height:1.5;display:block;margin-top:7px}.continue-button{width:100%;margin-top:17px;padding:13px;border:1px solid #c5a06a;background:#b68b53;color:#181715;font:10px 'DM Mono',monospace;letter-spacing:1.3px;cursor:pointer}.continue-button:hover{background:#d6b27a}.continue-button span{float:right;font-size:15px;line-height:10px}.gameover-overlay .upgrade-panel h2{font-size:28px}.touch-controls{display:none}.footer{height:36px;flex-shrink:0;display:flex;align-items:flex-end;justify-content:space-between;color:#716e69;font:8px 'DM Mono',monospace;letter-spacing:1.2px;padding:0 5px 1px}.footer-right b{color:#b18e5d;margin-left:6px}
@media(max-width:700px){body{padding:0;background:#111}.game-shell{width:100%;height:100dvh}.topbar{height:55px;padding:0 13px 4px;grid-template-columns:1fr auto}.chapter{display:none}.brand{font-size:12px}.top-actions{gap:9px}.run-badge{font-size:7px;padding:7px 8px}.sound-label{display:none}.game-frame{border-left:0;border-right:0;box-shadow:none}.hud-top{top:12px;left:10px;right:10px}.hero-card{width:160px;height:56px;padding:7px;gap:7px}.hero-portrait{height:39px;width:33px;font-size:20px}.hero-label{font-size:7px}.health-row{margin:5px 0 3px}.heart{height:5px}.health-caption{font-size:7px}.wave-card{width:130px;padding:7px 8px}.wave-card strong{font-size:9px;margin:4px 0 6px}.wave-label{font-size:7px}.kill-card{padding:7px 8px;height:42px;gap:5px;font-size:7px}.kill-card b{font-size:15px}.kill-skull{font-size:14px}.objective{top:80px;font-size:7px}.bottom-hud{left:10px;right:10px;bottom:max(116px,calc(env(safe-area-inset-bottom) + 108px));align-items:flex-end}.weapon-card{width:190px;height:57px;gap:7px;padding:6px}.weapon-icon{height:41px;width:33px;font-size:20px}.weapon-label{font-size:6px}.weapon-card strong{font-size:9px}.weapon-sub{font-size:7px}.weapon-damage{font-size:15px}.mini-map-wrap{width:92px;padding:5px}.mini-map-wrap>span{font-size:6px}.mini-map-wrap canvas{width:80px;height:52px}.controls-hint{display:none}.touch-controls{display:flex;position:absolute;left:14px;right:14px;bottom:max(16px,env(safe-area-inset-bottom));height:88px;justify-content:space-between;align-items:center;pointer-events:none}.dpad,.touch-actions{pointer-events:auto}.dpad{width:98px;height:88px;display:flex;flex-direction:column;align-items:center;justify-content:space-between}.dpad div{display:flex;gap:17px}.dpad button,.touch-actions button{border:1px solid #d5b77c66;background:#1d1b19d9;color:#dfc899;text-shadow:0 1px 3px #000;border-radius:6px;width:34px;height:32px;font-size:12px;touch-action:none;user-select:none}.dpad button:active,.touch-actions button:active{background:#8c6741}.touch-actions{display:flex;align-items:center;gap:10px}.touch-actions button{height:57px;width:57px;border-radius:50%;font:8px 'DM Mono',monospace;letter-spacing:.5px}.touch-actions .touch-attack{width:66px;height:66px;background:#8b5136dd;border-color:#e7a77388;color:#fff0d9}.footer{display:none}.upgrade-panel{padding:22px 16px}.upgrade-panel h2{font-size:25px}.upgrade-option{min-height:124px;padding:10px 6px}.upgrade-option strong{font-size:10px}.upgrade-option small{font-size:8px}.upgrade-option .option-icon{font-size:20px}}
