(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const mini = document.querySelector('#minimap');
  const mctx = mini.getContext('2d');
  const W = 960, H = 600;
  const keys = new Set();
  const mouse = { x: W * .7, y: H * .5, active: false };
  const palette = ['#d7ad72','#93a8a0','#bc775e','#9b88b4'];
  const names = ['IRON FALCHION','MOONLIT SABRE','EMBERBITE','VOID CLEAVER'];
  const types = ['BALANCED','QUICK · PRECISE','BURNING · FIERCE','HEAVY · RENDING'];
  const hero = { x: W/2, y: H/2+24, r: 12, hp: 100, maxHp:100, speed:190, damage:18, attackRate:.42, attackCD:0, attackT:0, dashCD:0, dashT:0, invuln:0, aim:0, color:palette[0], weapon:0, kills:0, floor:1, upgrades:0, power:0 };
  let enemies=[], particles=[], sparks=[], pickups=[], decor=[], queue=0, spawnT=0, roomTime=0, gameState='playing', soundOn=true, audio=null, toastTimer=0, gateGlow=0, swingCount=0;
  const floorNames=['THE ASHEN VAULT','HALL OF A THOUSAND EDGES','THE SUNKEN ARMORY','BLACKIRON CATACOMBS','THE KING’S LAST FORGE'];
  const random=(a,b)=>a+Math.random()*(b-a);
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}
  new ResizeObserver(resize).observe(canvas); resize();
  function audioCtx(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();return audio}
  function tone(freq,duration=.08,type='sine',volume=.035,slide=0){if(!soundOn)return;try{const a=audioCtx(),o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.setValueAtTime(freq,a.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,freq+slide),a.currentTime+duration);g.gain.setValueAtTime(volume,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+duration);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+duration)}catch(_){}}
  function showToast(text,time=2){document.querySelector('#toastText').textContent=text;document.querySelector('#toast').classList.add('show');toastTimer=time}
  function generateDecor(){decor=[]; // Weapon racks and abandoned swords around the chamber
    for(let i=0;i<15;i++){
      const side=i%4, t=random(.12,.88);let x,y;
      if(side===0){x=55+t*850;y=49+random(1,14)}else if(side===1){x=55+t*850;y=535+random(2,12)}else if(side===2){x=53+random(2,13);y=72+t*440}else{x=894+random(0,12);y=72+t*440}
      decor.push({x,y,angle:random(-.5,.5),kind:i%3===0?'rack':'sword',seed:random(0,100)});
    }
    for(let i=0;i<9;i++)decor.push({x:random(120,840),y:random(100,500),angle:random(0,Math.PI),kind:'floorSword',seed:random(0,100)});
  }
  function spawnRoom(){enemies=[];particles=[];sparks=[];pickups=[];hero.x=W/2;hero.y=H/2+20;hero.hp=Math.min(hero.maxHp,hero.hp+12);queue=Math.min(5+hero.floor*2,22);if(hero.floor%3===0)queue+=1;spawnT=.6;roomTime=0;gateGlow=0;gameState='playing';document.querySelector('#roomName').textContent=floorNames[(hero.floor-1)%floorNames.length];document.querySelector('#floorNum').textContent=String(hero.floor).padStart(2,'0');document.querySelector('#objective').innerHTML='<span class="objective-icon">✧</span><span>THE ARMORY stirs... STEEL YOURSELF</span>';generateDecor();updateHUD()}
  function enemyType(){if(hero.floor%3===0&&queue===1)return'boss';const roll=Math.random();if(hero.floor>1&&roll>.78)return'brute';if(hero.floor>1&&roll>.55)return'archer';return'grunt'}
  function spawnEnemy(){const edge=Math.floor(Math.random()*4);let x,y;if(edge===0){x=random(90,870);y=85}else if(edge===1){x=random(90,870);y=520}else if(edge===2){x=75;y=random(100,500)}else{x=885;y=random(100,500)}const kind=enemyType();const scale=1+Math.min(hero.floor-1,12)*.12;const cfg={grunt:[12,43,17,1,'#b87861'],brute:[25,25,32,1.8,'#9b6158'],archer:[9,38,12,1,'#8e9e9c'],boss:[95,25,68,2.4,'#c08c4b']}[kind];enemies.push({x,y,r:kind==='boss'?24:kind==='brute'?16:12,hp:cfg[0]*scale,maxHp:cfg[0]*scale,speed:cfg[1]+Math.min(hero.floor,12)*1.5,damage:cfg[2]*scale,kind,color:cfg[4],attackCD:random(.3,1),attackT:0,phase:random(0,6),flash:0,dead:false});if(kind==='boss')showToast('THE ARMORY’S CHAMPION HAS AWAKENED',2.4)}
  function attack(){if(gameState!=='playing'||hero.attackCD>0)return;hero.attackCD=hero.attackRate;hero.attackT=.23;swingCount++;let target=enemies.filter(e=>!e.dead).sort((a,b)=>dist(hero,a)-dist(hero,b))[0];if(!mouse.active&&target)hero.aim=Math.atan2(target.y-hero.y,target.x-hero.x);let reach=hero.weapon===3?80:hero.weapon===2?64:72,arc=hero.weapon===3?1.35:1.55,hit=0;
    for(const e of enemies){if(e.dead)continue;const dx=e.x-hero.x,dy=e.y-hero.y,d=Math.hypot(dx,dy),ang=Math.atan2(dy,dx);let diff=Math.atan2(Math.sin(ang-hero.aim),Math.cos(ang-hero.aim));if(d<reach+e.r&&Math.abs(diff)<arc/2){let dmg=hero.damage*(hero.weapon===3?1.5:hero.weapon===2?1.15:1)*(hero.power?1+hero.power*.08:1);e.hp-=dmg;e.flash=.13;e.x+=Math.cos(ang)*12;e.y+=Math.sin(ang)*12;hit++;for(let j=0;j<5;j++)sparks.push({x:e.x,y:e.y,vx:random(-100,100),vy:random(-120,30),life:random(.18,.42),color:hero.color,size:random(1.5,3.8)});if(e.hp<=0)killEnemy(e)}}
    if(hit){tone(hero.weapon===2?210:hero.weapon===3?100:320,.12,'sawtooth',.045,-160);if(hero.weapon===2)for(let i=0;i<3;i++)sparks.push({x:hero.x+Math.cos(hero.aim)*48,y:hero.y+Math.sin(hero.aim)*48,vx:random(-40,40),vy:random(-90,-20),life:.4,color:'#efa45c',size:4})}else tone(190,.08,'triangle',.022,-80);
  }
  function killEnemy(e){e.dead=true;hero.kills++;if(Math.random()<.14||e.kind==='boss')pickups.push({x:e.x,y:e.y,type:e.kind==='boss'?'relic':'heart',pulse:0});for(let i=0;i<12;i++)sparks.push({x:e.x,y:e.y,vx:random(-95,95),vy:random(-100,90),life:random(.25,.65),color:e.color,size:random(2,4)});tone(e.kind==='boss'?90:140,.18,'triangle',.05,-50);updateHUD()}
  function dash(){if(gameState!=='playing'||hero.dashCD>0)return;let dx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),dy=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0);if(!dx&&!dy){dx=Math.cos(hero.aim);dy=Math.sin(hero.aim)}let len=Math.hypot(dx,dy)||1;hero.dashDX=dx/len;hero.dashDY=dy/len;hero.dashCD=1.35;hero.dashT=.2;hero.invuln=.34;tone(440,.12,'sawtooth',.028,380)}
  function updateHUD(){const health=document.querySelector('#health');health.innerHTML='';for(let i=0;i<10;i++){let h=document.createElement('span');h.className='heart'+(hero.hp>i*10?' full':'');health.appendChild(h)}document.querySelector('#healthText').textContent=`${Math.ceil(hero.hp)} / ${hero.maxHp}`;document.querySelector('#killCount').textContent=hero.kills;document.querySelector('#weaponName').textContent=names[hero.weapon];document.querySelector('#weaponSub').textContent=`${types[hero.weapon]} · TIER ${Math.floor(hero.upgrades/2)+1}`;document.querySelector('#damageValue').innerHTML=`${Math.round(hero.damage)}<span>DMG</span>`;document.querySelector('#weaponIcon').style.color=hero.color;document.querySelector('#waveText').textContent=queue+enemies.length?`${queue+enemies.length} FOE${queue+enemies.length===1?'':'S'} REMAIN`:'VAULT CLEARED';document.querySelector('#waveBar').style.width=`${Math.max(0,100-(queue+enemies.length)/(5+hero.floor*2)*100)}%`}
  function chooseUpgrade(){gameState='upgrade';const choices=[{name:'GILDED EDGE',icon:'⚔',desc:'+8 blade damage<br>Every strike hits harder.',do:()=>{hero.damage+=8;hero.color=palette[0];hero.weapon=0}},{name:'WINDRUNNER',icon:'➶',desc:'Move and strike faster<br>Become a blur.',do:()=>{hero.speed+=22;hero.attackRate=Math.max(.22,hero.attackRate-.055);hero.weapon=1;hero.color=palette[1]}},{name:'EMBERBITE',icon:'♨',desc:'A blade that burns<br>Deal +15% damage.',do:()=>{hero.damage*=1.15;hero.weapon=2;hero.color=palette[2]}},{name:'VOID CLEAVER',icon:'✣',desc:'Slow, devastating blows<br>Longer reach, +50% damage.',do:()=>{hero.damage*=1.18;hero.weapon=3;hero.color=palette[3]}},{name:'BLOOD TITHE',icon:'♥',desc:'Restore 45 health<br>Grow tougher by 10.',do:()=>{hero.maxHp+=10;hero.hp=Math.min(hero.maxHp,hero.hp+45)}},{name:'HUNTER’S MARK',icon:'✧',desc:'+12% damage per relic<br>Build a deadly edge.',do:()=>{hero.power++;hero.damage*=1.06}}];const selected=[];while(selected.length<3){const o=choices[Math.floor(Math.random()*choices.length)];if(!selected.includes(o))selected.push(o)}const box=document.querySelector('#upgradeOptions');box.innerHTML='';selected.forEach(o=>{const el=document.createElement('button');el.className='upgrade-option';el.innerHTML=`<span class="option-icon">${o.icon}</span><strong>${o.name}</strong><small>${o.desc}</small>`;el.onclick=()=>{o.do();hero.upgrades++;updateHUD();document.querySelector('#upgradeOverlay').classList.remove('visible');document.querySelector('#upgradeOverlay').setAttribute('aria-hidden','true');gameState='transition';hero.floor++;document.querySelector('#objective').innerHTML='<span class="objective-icon">✧</span><span>THE DESCENT CONTINUES · FIND THE OPEN GATE</span>';showToast('A NEW BLADE. A DEEPER DARK.',2);setTimeout(()=>{if(gameState==='transition')spawnRoom()},1800)};box.appendChild(el)});document.querySelector('#upgradeOverlay').classList.add('visible');document.querySelector('#upgradeOverlay').setAttribute('aria-hidden','false');tone(520,.25,'sine',.04,280)}
  function endGame(){gameState='dead';document.querySelector('#runSummary').textContent=`You vanquished ${hero.kills} foes across ${hero.floor} floor${hero.floor===1?'':'s'}.`;document.querySelector('#gameoverOverlay').classList.add('visible');document.querySelector('#gameoverOverlay').setAttribute('aria-hidden','false');tone(160,.8,'sawtooth',.06,-120)}
